/bin/bash -lc "python3 -m py_compile openai_client.py && python3 - <<'PY'
import openai_client as client
sample = {\"output\": [{\"content\": [{\"type\": \"output_text\", \"text\": \"hello\"}, {\"type\": \"refusal\", \"refusal\": \"x\"}]}, {\"content\": [{\"type\": \"output_text\", \"text\": \" world\"}]}]}
assert client.output_text(sample) == \"hello world\"
for endpoint in (\"http://example.test/v1/responses\", \"not-a-url\"):
    try:
        client.create_response(\"x\", model=\"gpt-5-mini\", api_key=\"test\", endpoint=endpoint)
    except ValueError:
        pass
    else:
        raise AssertionError(endpoint)
print(\"checks passed\")
PY
rg -n \"(sk-[A-Za-z0-9]|OPENAI_API_KEY=|Authorization: Bearer)\" openai_client.py || true
git diff --check -- openai_client.py"

